"""Change-directed differential tests, generated by a model and kept only on execution evidence (brief 4, C1).

For changed functions the tests never called on the code before the change (side-by-side execution saw no input; below
Python 3.12, where it does not run, every comparable changed function),
the model is shown the function before and after and asked for probes: a few setup statements and one call
expression each. It never writes an assertion. Each probe is turned into a test of the project's own runner that
records what the call returned or raised, and the probe is kept only if it passes the filter chain:

1. it compiles;
2. it runs on the changed code (the probe's own setup does not fail);
3. it gives the same outcome five times on the changed code, each in a fresh process, the last from a second folder;
4. it runs a changed line (the reach tracer);
5. on the code before the change it gives one outcome twice, and that outcome differs.

An outcome is recorded with the tree's own folder, however the process spells it, written as ``<tree>``, so a
path into the tree is no difference by itself (sympy #30701). The code before runs at the same path as the first four
runs of the changed code, so an outcome that depends on the folder some other way (its name, its depth, the order of a
set of paths) is the same on both sides; one that changes with the folder is also dropped by the run from a second one.

A kept probe is reported as ``generated test shows a difference``, with both outcomes; the test written into the
comment asserts what executing the changed code produced. Spending is capped in dollars and minutes; the model's
own token counts price each call, and a call that could cross the dollar cap is not made.

Two backends write the probes, with the same prompt and the same filter. The Anthropic API, with ANTHROPIC_API_KEY,
billed per token under the dollar cap. Or, when no API key is set and it is asked for (``cli``), Claude Code's
``claude -p`` when the command is on PATH or CLAUDE_CODE_OAUTH_TOKEN is set: billed to the Claude plan as usage, so
only the minute cap applies. It runs in an empty folder with no tools, so the pull request's code never reaches it.
"""
from __future__ import annotations

import ast
import json
import os
import re
import shutil
import signal
import subprocess
import tempfile
import textwrap
import time
from pathlib import Path

from . import replay, runners, sidebyside, trust

KIND = 'generated test shows a difference'
MODEL = 'claude-opus-5-5'
PRICES = {  # dollars per million input / output tokens
    'claude-opus-5-5': (4.00, 20.00), 'claude-opus-5': (5.00, 25.00), 'claude-sonnet-5-5': (2.00, 10.00),
    'claude-haiku-5-5': (0.10, 0.50), 'claude-fable-5-1': (10.00, 50.00),
}
FALLBACK_MODELS = ('claude-opus-5-5', 'claude-opus-5', 'claude-fable-5-1', 'claude-sonnet-5-5')
MAX_FUNCTIONS = 5   # changed functions per request
MAX_TARGETS = 40    # changed functions probed in one run, the most changed first
KEEP = 8            # probes kept per function from one reply
REPEATS = 5         # runs on the changed code a probe must repeat in
EFFORT = 'low'      # a short, well-specified task under a cents-sized budget

SCHEMA = {
    'type': 'object',
    'properties': {'probes': {'type': 'array', 'items': {
        'type': 'object',
        'properties': {'function': {'type': 'string'}, 'setup': {'type': 'string'}, 'call': {'type': 'string'},
                       'why': {'type': 'string'}},
        'required': ['function', 'setup', 'call', 'why'], 'additionalProperties': False}}},
    'required': ['probes'], 'additionalProperties': False,
}

SYSTEM = (
    "You write probes that look for inputs a change to a Python function may have broken. A probe is a few setup "
    "statements and one call expression of the changed function (or of public code that reaches it). Do not write "
    "assertions or expected values: the probe is executed on the code before and after the change, and its outcomes "
    "are compared by the harness. The project's own tests already pass on both versions, so the ordinary inputs are "
    "covered. Choose inputs a caller could legitimately have passed to the code before the change, that reach the "
    "changed lines, and that the change may treat differently without meaning to: another type the old code accepted "
    "(a tuple, a generator, a subclass, a lazy or proxy object, an object that only has the needed method), an empty, "
    "falsy or None value, a boundary value, an argument left out, a value in an older or alternative format. Prefer "
    "inputs on which the old code returned normally. Use only names importable from the project; import what you use "
    "in the setup. Keep each probe deterministic: no time, randomness, network, or files outside a temporary directory.")


def probes_per_function(count):
    """How many probes to ask for per function: more when the change is in few functions."""
    return 8 if count <= 2 else 5 if count <= 6 else 3


class _Unannotated(ast.NodeTransformer):
    """A def statement as it runs when nothing reads its annotations."""

    def visit_arg(self, node):
        node.annotation = None
        return node

    def visit_FunctionDef(self, node):
        node.returns = None
        return self.generic_visit(node)
    visit_AsyncFunctionDef = visit_FunctionDef

    def visit_AnnAssign(self, node):
        if node.value is None:
            return ast.Pass()
        return self.generic_visit(ast.Assign(targets=[node.target], value=node.value))


def _weight(old, new):
    """How much of a function's running code the change alters: lines of its syntax tree, annotations, decorators
    and docstring set aside, that are on one side only. 0 when only those changed."""
    import copy
    import difflib

    def lines(node):
        node = _Unannotated().visit(copy.deepcopy(node))
        node.decorator_list = []
        if ast.get_docstring(node, clean=False) is not None:
            node.body = node.body[1:] or [ast.Pass()]
        return ast.dump(node, indent=0).splitlines()
    a, b = lines(old), lines(new)
    return sum(1 for row in difflib.ndiff(a, b) if row[:1] in '+-')


def targets(functions, before_src, after_src):
    """The functions to probe, the most changed first, and {id: reason} for changed functions left out. ``functions``
    are analyze's changed_functions rows (file, symbol).

    A probe is a call from outside, so the target need not be comparable call by call as side-by-side needs: a
    function nested in another is probed through the one that holds it, and a generator, or a function that became
    one, is a target like any other. Left out: a function in a test file, one that is not on both sides, a
    coroutine, and one whose running code is the same (only annotations, decorators, docstring or layout changed)."""
    found, skipped = {}, {}
    for row in functions:
        path, qual = row['file'], row['symbol']
        ident = f'{path}#{qual}'
        if replay.is_test_file(path):
            skipped[ident] = 'in a test file'
            continue
        before, after = before_src.get(path), after_src.get(path)
        parts = [part for part in qual.split('.') if part != '<locals>']
        old = new = None
        while parts and before and after:
            old, new = sidebyside._node(before, '.'.join(parts)), sidebyside._node(after, '.'.join(parts))
            if old is not None and new is not None:
                break
            old = new = None
            parts.pop()
        if old is None or new is None:
            skipped[ident] = 'not on both sides (new or removed)'
            continue
        holder = f"{path}#{'.'.join(parts)}"
        if holder in found:
            continue
        if isinstance(old, ast.AsyncFunctionDef) or isinstance(new, ast.AsyncFunctionDef):
            skipped[ident] = 'coroutine'
            continue
        weight = _weight(old, new)
        if not weight:
            skipped[ident] = 'only its annotations, decorators, docstring or layout changed'
            continue
        found[holder] = dict(id=holder, file=path, qual='.'.join(parts), name=parts[-1], weight=weight,
                             before=sidebyside._source(before, old), after=sidebyside._source(after, new))
    ranked = sorted(found.values(), key=lambda t: -t['weight'])
    for t in ranked[MAX_TARGETS:]:
        skipped[t['id']] = f'more than {MAX_TARGETS} changed functions: the {MAX_TARGETS} most changed were probed'
    return ranked[:MAX_TARGETS], skipped


def client():
    """The Anthropic client, or None when the SDK or credentials are missing."""
    try:
        import anthropic
    except ImportError:
        return None
    try:
        return anthropic.Anthropic()
    except Exception:
        return None


class ClaudeCLI:
    """The subscription backend: Claude Code's ``claude -p``, billed to the Claude plan, not per token."""
    name = 'claude -p'

    def __init__(self, command):
        self.command = command


CLI_SECONDS = 300  # one ``claude -p`` request at most


def backend(cli=False):
    """Who writes the probes: the Anthropic client; or, with ``cli`` and no ANTHROPIC_API_KEY, ``claude -p`` when the
    command is on PATH or CLAUDE_CODE_OAUTH_TOKEN is set. None when neither is available."""
    if cli and not os.environ.get('ANTHROPIC_API_KEY') and (shutil.which('claude') or os.environ.get('CLAUDE_CODE_OAUTH_TOKEN')):
        return ClaudeCLI(shutil.which('claude') or 'claude')
    return client()


def ask_cli(cli, model, targets, examples, seconds, probes=3):
    """One request through ``claude -p``. Returns (probes, 0.0, problem or None): its cost is plan usage."""
    command = [cli.command, '-p', '--output-format', 'json', '--model', model, '--system-prompt', SYSTEM,
               '--json-schema', json.dumps(SCHEMA), '--tools', '', '--no-session-persistence', '--strict-mcp-config',
               '--disable-slash-commands']
    # Only what Claude Code needs to sign in and run: nothing of the project's environment.
    env = {k: v for k, v in os.environ.items() if k in ('PATH', 'HOME', 'USER', 'LANG', 'TMPDIR', 'CLAUDE_CODE_OAUTH_TOKEN')}
    with tempfile.TemporaryDirectory(prefix='amu-claude-') as empty:
        try:
            process = subprocess.Popen(command, cwd=empty, env=env, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                       stderr=subprocess.PIPE, text=True, start_new_session=True)
        except OSError as exc:
            return [], 0.0, f'claude -p could not start: {exc.strerror or exc}'
        try:
            stdout, stderr = process.communicate(prompt(targets, examples, probes), timeout=max(1, seconds))
        except subprocess.TimeoutExpired:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except OSError:
                pass
            process.communicate()
            return [], 0.0, f'claude -p did not answer in {round(seconds)} s'
    try:
        reply = json.loads(stdout)
    except ValueError:
        reply = None
    if not isinstance(reply, dict):
        tail = (stderr or stdout or '').strip().splitlines()[-1:] or ['no output']
        return [], 0.0, f'claude -p exited with status {process.returncode} and no readable reply: {tail[0][:160]}'
    if reply.get('is_error') or process.returncode:
        return [], 0.0, f"claude -p failed: {str(reply.get('result') or reply.get('subtype') or process.returncode)[:160]}"
    answer = reply.get('structured_output')
    if not isinstance(answer, dict):
        body = str(reply.get('result') or '').strip()
        body = body.split('\n', 1)[1].rsplit('```', 1)[0] if body.startswith('```') and '\n' in body else body
        try:
            answer = json.loads(body)
        except ValueError:
            answer = None
    if not isinstance(answer, dict) or not isinstance(answer.get('probes'), list):
        return [], 0.0, 'the model returned no readable probes'
    return _kept(answer['probes'], targets), 0.0, None


def _kept(probes, targets):
    """The probes for known functions, at most KEEP each."""
    known, kept, count = {t['id'] for t in targets}, [], {}
    for probe in probes:
        if isinstance(probe, dict) and probe.get('function') in known and count.get(probe['function'], 0) < KEEP:
            count[probe['function']] = count.get(probe['function'], 0) + 1
            kept.append(probe)
    return kept


def cost(model, usage):
    price_in, price_out = PRICES.get(model, PRICES[MODEL])
    tokens_in = (getattr(usage, 'input_tokens', 0) or 0) + (getattr(usage, 'cache_creation_input_tokens', 0) or 0)
    tokens_out = getattr(usage, 'output_tokens', 0) or 0
    return (tokens_in * price_in + tokens_out * price_out) / 1_000_000


def prompt(targets, examples, probes=3):
    parts = ['Changed functions, as they were and as changed:\n']
    for t in targets:
        parts.append(f"## {t['id']}\n### before\n```python\n{t['before']}```\n### after\n```python\n{t['after']}```\n")
    if examples:
        parts.append('An existing test from this project, for how its tests import and set things up:\n```python\n'
                     + examples[:3000] + '\n```\n')
    parts.append(f'Write up to {probes} probes per function, each with a different kind of input. In "function" give '
                 'the function id as written above.')
    return '\n'.join(parts)


def ask(api, model, targets, examples, dollars_left, probes=3):
    """One request. Returns (probes, dollars spent, problem or None)."""
    text = prompt(targets, examples, probes)
    price_in, price_out = PRICES.get(model, PRICES[MODEL])
    tokens_in = len(SYSTEM + text) / 3 + 200  # a generous estimate; the bill uses the real count
    room = dollars_left - tokens_in * price_in / 1_000_000
    max_tokens = int(min(8000, room * 1_000_000 / price_out))
    if max_tokens < 1500:
        return [], 0.0, f'the dollar cap leaves too little for one request (${dollars_left:.3f})'
    params = dict(model=model, max_tokens=max_tokens, system=SYSTEM, messages=[{'role': 'user', 'content': text}],
                  output_config={'effort': EFFORT, 'format': {'type': 'json_schema', 'schema': SCHEMA}})
    try:
        if model in FALLBACK_MODELS:
            # A declined request is rerun server-side on the model Anthropic picks for the refusal category.
            response = api.beta.messages.create(betas=['server-side-fallback-2026-07-01'], fallbacks='default', **params)
        else:
            response = api.messages.create(**params)
    except Exception as exc:  # the comparison stands without generated tests; say why
        return [], 0.0, f'model request failed: {type(exc).__name__}: {str(exc)[:160]}'
    spent = cost(model, response.usage)
    if response.stop_reason == 'refusal':
        return [], spent, 'the model declined the request'
    if response.stop_reason == 'max_tokens':
        return [], spent, 'the model ran out of the tokens the dollar cap allowed'
    body = next((b.text for b in response.content if b.type == 'text'), '')
    try:
        probes = json.loads(body).get('probes', [])
    except ValueError:
        return [], spent, 'the model returned no readable probes'
    return _kept(probes, targets), spent, None


RECORDER = '''
import json as _amu_json, os as _amu_os, re as _amu_re
_AMU_ADDRESS = _amu_re.compile(r" at 0x[0-9a-fA-F]+")
_AMU_TREE = _amu_json.loads(_amu_os.environ.get("AMU_C1_TREE") or "[]")


def _amu_record(probe, kind, value):
    try:
        shown = repr(value)
    except Exception as exc:
        shown = "<repr failed: %s>" % type(exc).__name__
    shown = _AMU_ADDRESS.sub(" at 0x?", shown)
    for spelling in _AMU_TREE:  # longest first, and before the cut, so both sides are cut at the same place
        shown = shown.replace(spelling, "<tree>")
    outcome = [kind, type(value).__qualname__, shown[:2000]]
    at = None
    if kind == "raise":  # the deepest frame in the tree the exception passed through: where the project's code let it out
        step = value.__traceback__
        while step is not None:
            name = _amu_os.path.realpath(step.tb_frame.f_code.co_filename)
            for spelling in _AMU_TREE:
                if name.startswith(spelling + _amu_os.sep) and "site-packages" not in name:
                    at = [name[len(spelling) + 1:], step.tb_lineno]
                    break
            step = step.tb_next
    with open(_amu_os.environ["AMU_C1_OUT"], "a") as handle:
        handle.write(_amu_json.dumps(dict(probe=probe, outcome=outcome, at=at)) + "\\n")
'''


def compiles(probe):
    try:
        ast.parse(probe['setup'] or 'pass')
        ast.parse(probe['call'], mode='eval')
        return True
    except (SyntaxError, ValueError, KeyError, TypeError):
        return False


def _body(index, probe):
    lines = textwrap.dedent(probe['setup'] or '').strip().splitlines() or ['pass']
    return [*lines, 'try:', f"    _amu_value = ({probe['call']})", 'except Exception as _amu_exc:',
            f'    _amu_record({index}, "raise", _amu_exc)', 'else:', f'    _amu_record({index}, "return", _amu_value)']


def _host(tree, probe):
    """The Django test app a probe imports from, if any. runtests.py installs only the apps its labels name, so a probe
    using an app's models has to be a test of that app: hosted anywhere else, the import itself raises."""
    try:
        nodes = ast.walk(ast.parse(textwrap.dedent(probe['setup'] or '')))
    except (SyntaxError, ValueError):
        return None
    for node in nodes:
        names = ([node.module] if isinstance(node, ast.ImportFrom) and node.module and not node.level else
                 [alias.name for alias in node.names] if isinstance(node, ast.Import) else [])
        for name in names:
            top = name.split('.')[0]
            if top.isidentifier() and (Path(tree)/'tests'/top/'__init__.py').is_file():
                return top
    return None


def test_file(runner_name, probes, tree=None):
    """({relative path: source}, {probe index: test id}) for the runner, or None when it cannot host generated tests."""
    if runner_name == 'pytest':
        path, ids, out = 'test_amu_generated.py', {}, [RECORDER]
        for i, probe in probes:
            out.append(f'\n\ndef test_amu_probe_{i}():\n' + textwrap.indent('\n'.join(_body(i, probe)), '    '))
            ids[i] = f'{path}::test_amu_probe_{i}'
        return {path: '\n'.join(out) + '\n'}, ids
    if runner_name in ('unittest', 'django-runtests'):
        django = runner_name == 'django-runtests'
        base = 'django.test.TestCase' if django else 'unittest.TestCase'
        module = base.rsplit('.', 1)[0]
        default = 'tests/amu_generated/tests.py' if django else 'test_amu_generated.py'
        files, ids = {}, {}
        for i, probe in probes:
            app = _host(tree, probe) if django and tree is not None else None
            path = f'tests/{app}/test_amu_generated.py' if app else default
            out = files.setdefault(path, [RECORDER, f'import {module}', '', f'class AmuGeneratedTests({base}):'])
            out.append(f'    def test_amu_probe_{i}(self):\n' + textwrap.indent('\n'.join(_body(i, probe)), '        '))
            ids[i] = f'{path}::AmuGeneratedTests::test_amu_probe_{i}'
        return {path: '\n'.join(out) + '\n' for path, out in files.items()}, ids
    return None


def _outcomes(path, origins=None):
    found = {}
    try:
        lines = Path(path).read_text().splitlines()
    except OSError:
        return found
    for line in lines:
        try:
            row = json.loads(line)
        except ValueError:
            continue
        found.setdefault(row['probe'], []).append(row['outcome'])
        if origins is not None and row.get('at'):
            origins[row['probe']] = row['at']
    return found


def _install(tree, files):
    made = []
    for rel, source in files.items():
        target = Path(tree)/rel
        target.parent.mkdir(parents=True, exist_ok=True)
        if rel.startswith('tests/amu_generated/') and not (target.parent/'__init__.py').exists():
            (target.parent/'__init__.py').write_text('')
            made.append(target.parent/'__init__.py')
        target.write_text(source)
        made.append(target)
    return made


def _remove(paths):
    for path in paths:
        Path(path).unlink(missing_ok=True)
    for path in paths:
        try:
            Path(path).parent.rmdir()
        except OSError:
            pass


def _spellings(tree):
    """The tree's folder as a process may spell it, longest first: as given, resolved, and on macOS without the
    /private that /var and /tmp are links into."""
    real = os.path.realpath(tree)
    names = {os.path.abspath(tree), real}
    for name in list(names):
        if name.startswith('/private/') and os.path.realpath(name[len('/private'):]) == real:
            names.add(name[len('/private'):])
    return sorted((name for name in names if name.strip(os.sep)), key=len, reverse=True)


def _run(runner, python, tree, ids, scratch, name, timeout, extra=None, said=None, origins=None):
    """``said``, a list when given, gets what the runner reported: its problem, then its text per test that did not pass."""
    out = Path(scratch)/f'c1-{name}.jsonl'
    out.unlink(missing_ok=True)
    texts = {} if said is not None else None
    _, problem = runners.execute(runner, python, tree, ids, Path(scratch)/f'c1-{name}.xml', timeout, texts=texts,
                                 extra_env=dict(extra or {}, AMU_C1_OUT=str(out), AMU_C1_TREE=json.dumps(_spellings(tree))))
    if said is not None:
        said += ([str(problem)] if problem else []) + [str(row.get('text', '')) for row in texts.values() if row.get('text')]
    return _outcomes(out, origins)


def run(runner, python, after_tree, before_tree, targets, changed, examples, scratch, dollars, minutes, model=MODEL, api=None,
        copy_before=False, cli=False):
    """Generate, filter and compare. ``targets`` are sidebyside.targets entries; ``changed`` is {path: changed lines on
    the changed side}. ``cli`` allows the ``claude -p`` backend when no API key is set. Returns (info, differences, gaps)."""
    started = time.monotonic()
    info = dict(model=model, dollars_cap=dollars, minutes_cap=minutes, functions=len(targets), requests=0, cost=0.0,
                proposed=0, compiled=0, ran=0, stable=0, reached=0, differed=0, accepted=0, backend='api')
    gaps, differences = [], []
    if not targets or minutes <= 0 or dollars <= 0 and not cli:
        return info, differences, gaps
    api = api or backend(cli)
    subscription = isinstance(api, ClaudeCLI)
    if api is None:
        gaps.append('generated tests: no Anthropic SDK or credentials' + (', and no claude command or CLAUDE_CODE_OAUTH_TOKEN'
                                                                         if cli else '') + ', so none were generated')
        return info, differences, gaps
    if not subscription and dollars <= 0:
        return info, differences, gaps
    if subscription:
        info.update(backend=api.name, cost_basis='plan usage')
    hosted = test_file(runner.name, [])
    if hosted is None:
        gaps.append(f'generated tests: the {runner.name} runner cannot host them yet')
        return info, differences, gaps

    def left():
        return minutes * 60 - (time.monotonic() - started)
    probes, per = [], probes_per_function(len(targets))
    for start in range(0, len(targets), MAX_FUNCTIONS):
        if not subscription and dollars - info['cost'] <= 0 or left() < 30:
            gaps.append('generated tests: the dollar or minute cap was reached before every changed function had probes')
            break
        if subscription:
            found, spent, problem = ask_cli(api, model, targets[start:start + MAX_FUNCTIONS], examples, min(CLI_SECONDS, left()), per)
        else:
            found, spent, problem = ask(api, model, targets[start:start + MAX_FUNCTIONS], examples, dollars - info['cost'], per)
        info['requests'] += 1 if spent or not problem else 0
        info['cost'] = round(info['cost'] + spent, 5)
        probes += found
        if problem:
            gaps.append('generated tests: ' + problem)
            if not found:
                break
    info['proposed'] = len(probes)
    numbered = [(i, p) for i, p in enumerate(probes) if compiles(p)]
    info['compiled'] = len(numbered)
    if not numbered or left() < 10:
        return info, differences, gaps
    files, ids = test_file(runner.name, numbered, after_tree)
    head, elsewhere = Path(scratch)/'c1-head', Path(scratch)/'c1-elsewhere'/'head'
    shutil.rmtree(head, ignore_errors=True)
    shutil.rmtree(elsewhere.parent, ignore_errors=True)
    shutil.copytree(after_tree, head, symlinks=True, ignore=shutil.ignore_patterns('.git', '.amu', '__pycache__'))
    _install(head, files)
    timeout = max(10, min(left(), 120))
    said, origins = [], {}
    runs = [_run(runner, python, head, list(ids.values()), scratch, f'head-{n}', timeout, said=said if n == 0 else None,
                 origins=origins if n == 0 else None)
            for n in range(REPEATS - 1)]
    # The last run is from a folder of another name and depth: an outcome that changes with where the tree lives is
    # not stable. The tree stays there for the reach runs.
    elsewhere.parent.mkdir(parents=True)
    head = head.rename(elsewhere)
    runs.append(_run(runner, python, head, list(ids.values()), scratch, f'head-{REPEATS - 1}', timeout))
    first = runs[0]
    ran = [i for i, _ in numbered if len(first.get(i, [])) == 1]
    info['ran'] = len(ran)
    if len(ran) < len(numbered):
        # A probe that recorded nothing never got to its call: the reader is told what the runner said, not left with a zero.
        lines = [line.strip().removeprefix('E ').strip() for line in (said[0] if said else '').splitlines() if line.strip()]
        last = [line for line in lines if re.match(r'[\w.]*(Error|Exception|Warning)\b.*: ', line)][-1:] or lines[-1:]
        gaps.append(f'generated tests: {len(numbered) - len(ran)} of {len(numbered)} probes did not run on the head'
                    + (f' ({last[0][:200]})' if last else ''))
    stable = [i for i in ran if all(r.get(i) == first[i] for r in runs[1:])]
    info['stable'] = len(stable)
    reached = []
    folder = trust.support(scratch, {name: set(lines) for path, lines in changed.items() if lines
                                     for name in {str(head/path), str((head/path).resolve())}})
    for i in stable:
        where = Path(scratch)/f'c1-reach-{i}'
        shutil.rmtree(where, ignore_errors=True)
        _run(runner, python, head, [ids[i]], scratch, f'reach-{i}', timeout, trust._env(folder, reach=where))
        hits = trust._hits(where)
        if hits:
            reached.append(i)
    info['reached'] = len(reached)
    if reached:
        # The code before runs at the very path of the first head runs, so nothing about the location (its spelling,
        # length, depth, name, or the hash order of paths in it) differs between the two sides.
        copy = Path(scratch)/'c1-head'
        shutil.rmtree(copy, ignore_errors=True)
        shutil.copytree(before_tree, copy, symlinks=True, ignore=shutil.ignore_patterns('.git', '.amu', '__pycache__'))
        before_tree = copy
        made = _install(before_tree, files)
        try:
            base = [_run(runner, python, before_tree, [ids[i] for i in reached], scratch, f'base-{n}', timeout) for n in range(2)]
        finally:
            _remove(made)
        for i in reached:
            before_outcome = base[0].get(i)
            if before_outcome and base[1].get(i) == before_outcome and before_outcome != first[i]:
                probe = dict(numbered)[i]
                differences.append(dict(label=KIND, target=probe['function'], setup=probe['setup'], call=probe['call'],
                                        why=probe.get('why', ''), before=before_outcome[0], after=first[i][0],
                                        test=written_test(probe, first[i][0])))
                if before_outcome[0][0] == 'return' and first[i][0][0] == 'raise':
                    differences[-1]['origin'] = origin(after_tree, origins.get(i), set(files))
                    differences[-1]['at'] = origins.get(i)
        differences[:] = ordered(differences)
        info['differed'] = len(differences)
    info['accepted'] = len(differences)
    info['seconds'] = round(time.monotonic() - started, 1)
    shutil.rmtree(elsewhere.parent, ignore_errors=True)
    shutil.rmtree(Path(scratch)/'c1-head', ignore_errors=True)
    return info, differences, gaps


def origin(tree, at, hosts):
    """Why a call that returned on the merge base raises on the head, from where the exception left the project's code:
    'raised' by a raise statement there, 'call' when it never got past the probe's own call (the arguments no longer
    fit, or code outside the project refused them), else 'crash': a statement that is not a raise let it out."""
    if not at or at[0] in hosts:
        return 'call'
    try:
        tree = ast.parse((Path(tree)/at[0]).read_text())
    except (OSError, SyntaxError, ValueError):
        return 'crash'
    inner = None
    for node in ast.walk(tree):
        if isinstance(node, ast.stmt) and node.lineno <= at[1] <= (node.end_lineno or node.lineno):
            if inner is None or node.lineno >= inner.lineno:
                inner = node
    return 'raised' if isinstance(inner, ast.Raise) else 'crash'


def ordered(differences):
    """The rows in the order a reader with room for a few should get them: every function's first row before any
    function's second, and within that a call that returned on the merge base and raises on the head first."""
    def broke(row):
        return row['before'][0] == 'return' and row['after'][0] == 'raise'
    turn, seen = [], {}
    for index, row in enumerate(sorted(differences, key=lambda row: not broke(row))):
        nth = seen[row['target']] = seen.get(row['target'], -1) + 1
        turn.append((nth, not broke(row), index, row))
    return [row for *_, row in sorted(turn, key=lambda item: item[:3])]


def written_test(probe, outcome):
    """The generated test as it would be committed: the assertion is what executing the changed code produced."""
    kind, type_name, shown = outcome
    if '<tree>' in shown:
        return ''  # the outcome names the tree's folder, which a committed test cannot know
    setup = textwrap.dedent(probe['setup'] or '').strip()
    if kind == 'raise':
        check = f"with pytest.raises({type_name}):\n    {probe['call']}"
    else:
        check = f"assert repr({probe['call']}) == {shown!r}"
    return 'import pytest\n\n\ndef test_generated():\n' + textwrap.indent((setup + '\n' if setup else '') + check, '    ') + '\n'


